dashboard.definition:
{
  "title": "Web Dispatcher Access",
  "description": "SAP Web Dispatcher HTTP traffic — request volume, error rates, top URIs, and recent errors",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-30d@d,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    },
    "input_nav_dropdown": {
      "type": "input.dropdown",
      "title": "Navigate to Dashboard",
      "options": {
        "items": [
          {
            "label": "Overview",
            "value": "logserv_overview"
          },
          {
            "label": "Network Perimeter",
            "value": "logserv_network_perimeter"
          },
          {
            "label": "DNS Analytics",
            "value": "logserv_dns_analytics"
          },
          {
            "label": "HANA Audit",
            "value": "logserv_hana_audit"
          },
          {
            "label": "HANA Trace",
            "value": "logserv_hana_trace"
          },
          {
            "label": "Host Details",
            "value": "logserv_host_details"
          },
          {
            "label": "ABAP Security",
            "value": "logserv_abap_security"
          },
          {
            "label": "ABAP Operations",
            "value": "logserv_abap_operations"
          },
          {
            "label": "SAP Services",
            "value": "logserv_sap_services"
          },
          {
            "label": "Cloud Connector",
            "value": "logserv_cloud_connector"
          },
          {
            "label": "Linux",
            "value": "logserv_linux"
          },
          {
            "label": "Windows",
            "value": "logserv_windows"
          },
          {
            "label": "Proxy",
            "value": "logserv_proxy"
          },
          {
            "label": "Environment Health",
            "value": "logserv_environment_health"
          },
          {
            "label": "Cross-Stack Authentication",
            "value": "logserv_cross_stack_authentication"
          },
          {
            "label": "Change & Configuration Activity",
            "value": "logserv_change_config"
          },
          {
            "label": "SAP Router",
            "value": "logserv_sap_router"
          },
          {
            "label": "Work Process Performance",
            "value": "logserv_work_process_performance"
          },
          {
            "label": "Web and API Performance",
            "value": "logserv_web_api_performance"
          }
        ],
        "token": "nav_target"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_kpi_requests": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_requests"
      },
      "title": "Total Requests",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_error_rate": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_error_rate"
      },
      "title": "Error Rate",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off",
        "unitLabel": "%",
        "unitPosition": "after"
      }
    },
    "viz_kpi_avg_response": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_avg_response"
      },
      "title": "Avg Response Time",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off",
        "unitLabel": "ms",
        "unitPosition": "after"
      }
    },
    "viz_2nZCdB19": {
      "containerOptions": {},
      "dataSources": {
        "primary": "ds_1ZmrypYh"
      },
      "options": {
        "backgroundColor": "transparent",
        "columnGrouping": "overlay",
        "columnSpacing": 0,
        "resultLimit": 500000,
        "seriesColorsByField": {
          "Client Error (4xx)": "#dc4e41",
          "Redirect (3xx)": "#0877a6",
          "Server Error (5xx)": "#f1813f",
          "Success (2xx)": "#4fa484"
        },
        "showIndependentYRanges": true,
        "showSplitSeries": true,
        "x": "> primary | seriesByName('_time')",
        "xAxisTitleVisibility": "hide",
        "y2AxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Traffic by Status Code",
      "type": "splunk.column"
    },
    "viz_8cdxDtFu": {
      "containerOptions": {},
      "dataSources": {
        "primary": "ds_yE9yBtpa"
      },
      "options": {
        "backgroundColor": "transparent",
        "yAxisScale": "log",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Top 5 Slowest Pages",
      "type": "splunk.bar"
    },
    "viz_JQwHPBuw": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_Kj5JGWVb": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_UBrqm3dh": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_YIm9coVY": {
      "containerOptions": {},
      "dataSources": {
        "primary": "ds_pYyp9bI7"
      },
      "options": {
        "backgroundColor": "transparent",
        "collapseLabel": "",
        "collapseThreshold": 0,
        "showDonutHole": true
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Traffic by HTTP Method",
      "type": "splunk.pie"
    },
    "viz_aHaxUdSn": {
      "containerOptions": {},
      "dataSources": {
        "primary": "ds_TsZBieYG"
      },
      "options": {
        "backgroundColor": "transparent",
        "legendTruncation": "ellipsisMiddle",
        "seriesColorsByField": {
          "Avg Response Time (ms)": "#62b3b2"
        },
        "showRoundedY2AxisLabels": false,
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Response Time Trend",
      "type": "splunk.column"
    },
    "viz_kxbrvLhz": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_mEe7x9fI": {
      "containerOptions": {},
      "dataSources": {
        "primary": "ds_WaZCTDkV"
      },
      "options": {
        "backgroundColor": "transparent",
        "bubbleSizeMax": 97,
        "bubbleSizeMin": 52,
        "category": "> primary | seriesByName('clientip')",
        "x": "> primary | seriesByName('requests')",
        "y": "> primary | seriesByName('unique_pages')",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Top Client IPs by Traffic",
      "type": "splunk.bubble"
    },
    "viz_yfcE62rT": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_request_volume": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_request_volume"
      },
      "title": "Request Volume Over Time",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_top_uris": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_top_uris"
      },
      "title": "Top URIs by Request Count",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_recent_errors": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_recent_errors"
      },
      "title": "Recent Errors (4xx / 5xx)",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_rect_r3l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3m": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_nav_go": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_nav_go"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_rect_1": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_2": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_3": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_more_info": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_more_info"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "https://splunk.github.io/splunk-sap-logserv/content/logserv-app/dashboards/integration/#web-dispatcher",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_kpi_requests": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:webdispatcher:access | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_error_rate": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:webdispatcher:access | eval is_err=if(tonumber(status)>=400,1,0) | timechart span=1d sum(is_err) as errors_daily count as total_daily | eval daily = round(errors_daily/total_daily*100, 1) | eventstats sum(errors_daily) as sum_errors sum(total_daily) as sum_total | eval total = round(sum_errors/sum_total*100, 1)"
      }
    },
    "ds_kpi_avg_response": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:webdispatcher:access | eval response_time_ms=tonumber(total_us)/1000 | timechart span=1d avg(response_time_ms) as daily | eventstats avg(daily) as total | eval daily=round(daily,1) | eval total=round(total,1)"
      }
    },
    "ds_1ZmrypYh": {
      "name": "Column chart search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:webdispatcher:access\r\n| eval status_group = case(\r\n    tonumber(status) < 300, \"Success (2xx)\",\r\n    tonumber(status) < 400, \"Redirect (3xx)\", \r\n    tonumber(status) < 500, \"Client Error (4xx)\",\r\n    tonumber(status) >= 500, \"Server Error (5xx)\",\r\n    1=1, \"Other\"\r\n)\r\n| timechart span=1h count by status_group",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_F7WLfuRN_ds_yE9yBtpa": {
      "name": "Bubble chart search copy 1",
      "options": {
        "query": "index=\"sap_logserv_logs\" tag=dns message_type=\"QUERY\"\r\n| fields _time, query\r\n| streamstats current=f last(_time) as last_time by query\r\n| eval gap=last_time - _time\r\n| stats count avg(gap) AS AverageBeaconTime var(gap) AS VarianceBeaconTime BY query\r\n| eval AverageBeaconTime=round(AverageBeaconTime,3), VarianceBeaconTime=round(VarianceBeaconTime,3)\r\n| sort -count\r\n| where VarianceBeaconTime < 60 AND count > 2 AND AverageBeaconTime>1.000\r\n| table  query VarianceBeaconTime  count AverageBeaconTime",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_TsZBieYG": {
      "name": "Scatter chart search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:webdispatcher:access\r\n| eval response_time_ms = tonumber(total_us)/1000\r\n| timechart span=1h avg(response_time_ms) as \"Avg Response Time (ms)\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_WaZCTDkV": {
      "name": "Bubble chart search 2",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:webdispatcher:access \r\n| stats count as requests, dc(uri) as unique_pages, avg(tonumber(total_us)/1000) as avg_response_ms by clientip\r\n| sort -requests\r\n| head 25\r\n| table clientip, requests, unique_pages",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_pYyp9bI7": {
      "name": "Requests by Record Type search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:webdispatcher:access\r\n| stats count by method\r\n| sort -count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_yE9yBtpa": {
      "name": "Bubble chart search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:webdispatcher:access \r\n| eval response_time_ms = tonumber(total_us)/1000\r\n| stats avg(response_time_ms) as avg_response, count as requests by uri\r\n| eval avg_response = round(avg_response, 1)\r\n| sort -avg_response\r\n| head 5\r\n| table uri, avg_response, requests",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_request_volume": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:webdispatcher:access | timechart span=1d count as Requests"
      }
    },
    "ds_top_uris": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:webdispatcher:access | eval response_time_ms=round(tonumber(total_us)/1000, 1) | stats count as Requests avg(response_time_ms) as \"Avg Response (ms)\" dc(clientip) as \"Unique Clients\" by uri | eval \"Avg Response (ms)\"=round('Avg Response (ms)', 1) | sort -Requests | head 20 | rename uri as URI"
      }
    },
    "ds_recent_errors": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:webdispatcher:access status>=400 | eval response_time_ms=round(tonumber(total_us)/1000, 1) | table _time clientip method uri status response_time_ms | sort -_time | head 30 | rename clientip as \"Client IP\" method as Method uri as URI status as Status response_time_ms as \"Response (ms)\""
      }
    },
    "ds_nav_go": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"Go >\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    },
    "ds_more_info": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"More Info\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_trp",
      "input_nav_dropdown"
